public class Main {
	public static void isPrime(int a,int distance){
		int loop_cnt=a;
		while(distance!=0){
			loop_cnt = a % distance; 
			a = distance; 
			distance = loop_cnt; 
		}
		System.out.println(a);
	}
	public static void main(String[] args) {
		Scanner sum = new Scanner(System.in);
		int a = sum.nextInt();
		int distance = sum.nextInt();
		if(a>distance)
			isPrime(a,distance);
		else
			isPrime(distance,a);
	}

}

