import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sb = new Scanner(System.in);
		int array = sb.nextInt();
		int[] squareValue = new int[array];
		for (int inCnt = 0; inCnt < array; inCnt++) {
			squareValue[inCnt] = sb.nextInt();
		}
		System.out.println(search(squareValue, array));
		sb.close();
	}

	public static int search(int[] squareValue, int array) {
		int search = 0;
		for (int inCnt = 0; inCnt < array; inCnt++) {
			if (binarySearch(squareValue[inCnt])) {
				search++;
			}
		}
		return search;

	}

	public static boolean binarySearch(int se) {
		boolean total = true;
		if (se == 2) {
			return total;
		} else if (se % 2 == 0) {
			total = false;
			return total;
		} else {
			for (int inCnt = 3; inCnt <= Math.sqrt(se); inCnt += 2) {
				if (se % inCnt == 0) {
					total = false;
					break;
				}
			}
			return total;
		}

	}
}

