    private static BufferedReader floor = new BufferedReader(new InputStreamReader(System.in));    
    private static StringTokenizer lines;

    public static void main ( String [] args ) throws IOException
    {
	new Main().cal();
    }


    private void judge() throws IOException 
    {
	int N = Integer.parseInt(floor.readLine());
	int [] throw_str = new int[N];

	lines = new StringTokenizer(floor.readLine());
	for(int scan = 0; scan < N; scan++)
	    throw_str[scan] = Integer.parseInt(lines.nextToken());

	int ints = 0;
	for(int scan = 0; scan < throw_str.length; scan++)
	    for( int minimumIncurred = throw_str.length-1; minimumIncurred > scan; minimumIncurred--) {
		if ( throw_str[minimumIncurred] < throw_str[minimumIncurred-1] ) {
		    ints++;
		    si(throw_str, minimumIncurred, minimumIncurred-1);
		}

	    }

	for(int scan = 0; scan < throw_str.length; scan++){
	    if ( scan > 0 ) System.out.print(" ");
	    System.out.print(throw_str[scan]);
	}
	System.out.println("");

	System.out.println(ints);
    }

    private void si(int [] throw_str, final int scan, final int minimumIncurred) {
	int token = throw_str[minimumIncurred];
	throw_str[minimumIncurred] = throw_str[scan];
	throw_str[scan] = token;
    }

}

