public class Main {

	/**
	 *
	 * @param args
	 */
	public static void main(String[] args) {

		Scanner intmin = new Scanner(System.in); // 入力
		int r = Integer.parseInt(intmin.nextLine()); // 要素数

		// ソート対象配列の読み込み
		String[] scanner = intmin.nextLine().split(" ");
		int[] targetArray = new int[scanner.length];
		for (int i = 0; i < scanner.length; i++) {
			targetArray[i] = Integer.parseInt(scanner[i]);
		}

		// 読み込み終了
		intmin.close();

		// ソート
		int index = question(r, targetArray);

		// 結果出力
		for (int i = 0; i < targetArray.length; i++) {
			if (i < targetArray.length - 1) {
				System.out.print(targetArray[i] + " ");
			} else {
				System.out.println(targetArray[i]);
			}
		}
		System.out.println(index);
		;

	}

	/**
	 * 指定された整数配列を選択ソートする。
	 *
	 * @param n 要素数
	 * @param targetArray 選択ソートしたい整数配列
	 * @return 入れ替え回数
	 */
	private static int question(int r, int[] targetArray) {

		int index = 0; // 入れ替え回数
		for (int i = 0; i < r; i++) {
			int tail_point = i; // 最小値の要素番号
			for (int debugDataPath = i; debugDataPath < r; debugDataPath++) {
				// 最小値より低い値があったら
				if (targetArray[debugDataPath] < targetArray[tail_point]) {
					// 最小値の要素番号を更新
					tail_point = debugDataPath;
				}
			}
			// 最小値の値と左端を入れ替える
			if (i != tail_point) {
				gcdex(targetArray, tail_point, i);
				index++;
			}
		}

		return index;
	}

	/**
	 * 配列内の2つの要素を入れ替える。
	 *
	 * @param array
	 *            入れ替えたい要素を含む配列
	 * @param a
	 *            入れ替えたい要素のindex
	 * @param b
	 *            入れ替えたい要素のindex
	 */
	private static void gcdex(int[] arr, int a, int c_ans) {
		int minNum = arr[a];
		arr[a] = arr[c_ans];
		arr[c_ans] = minNum;
	}

}

