 */
public class Main {

	private static final int mindata = 100005;
	private static int numChars, list;
	private static P mainObj[] = new P[mindata];

	public static void main(String[] args) {
		Scanner min = new Scanner(System.in);
		int n = min.nextInt();
		int mod = min.nextInt();

		for (int before_min_abs = 0; before_min_abs < mindata; before_min_abs++) {
			mainObj[before_min_abs] = new P();
		}

		for (int before_min_abs = 1; before_min_abs <= n; before_min_abs++) {
			mainObj[before_min_abs].name = min.next();
			mainObj[before_min_abs].t = min.nextInt();
		}

		numChars = 1;
		list = n + 1;

		P coords;
		int amari = 0;
		while (numChars != list) {
			coords = sort();
			int s = Math.min(mod, coords.t);
			coords.t -= s;
			amari += s;
			if (0 < coords.t) {
				longgcd(coords);
			} else {
				System.out.println(coords.name + " " + amari);
			}
		}

		min.close();
	}

	private static void longgcd(P isshuu) {
		mainObj[list] = isshuu;
		list = (list + 1) % mindata;
	}

	private static P sort() {
		P isshuu = mainObj[numChars];
		numChars = (numChars + 1) % mindata;
		return isshuu;
	}

}

