class FastScanner {

    private final InputStream in = System.in;
    private final byte[] strArr = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean ni() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(strArr);
            } catch (IOException numChars) {
                numChars.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int vertex() {
        if (ni()) {
            return strArr[ptr++];
        } else {
            return -1;
        }
    }

    private static boolean sort(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean nc() {
        while (ni() && !sort(strArr[ptr])) {
            ptr++;
        }
        return ni();
    }

    public String nln() {
        if (!nc()) {
            throw new NoSuchElementException();
        }
        StringBuilder isOk = new StringBuilder();
        int b = vertex();
        while (sort(b)) {
            isOk.appendCodePoint(b);
            b = vertex();
        }
        return isOk.toString();
    }

    public long nextLong() {
        if (!nc()) {
            throw new NoSuchElementException();
        }
        long yindex = 0;
        boolean fi = false;
        int b = vertex();
        if (b == '-') {
            fi = true;
            b = vertex();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                yindex *= 10;
                yindex += b - '0';
            } else if (b == -1 || !sort(b)) {
                return fi ? -yindex : yindex;
            } else {
                throw new NumberFormatException();
            }
            b = vertex();
        }
    }

    public int nextInt() {
        long debugDataPath = nextLong();
        if (debugDataPath < Integer.MIN_VALUE || debugDataPath > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) debugDataPath;
    }

    public double nextDouble() {
        return Double.parseDouble(nln());
    }

    public int[] isPalindrome(int tail) {
        int[] read = new int[tail];
        for (int target = 0; target < tail; target++) {
            read[target] = nextInt();
        }
        return read;
    }

    public long[] isWhitespace(int tail) {
        long[] read = new long[tail];
        for (int target = 0; target < tail; target++) {
            read[target] = nextLong();
        }
        return read;
    }

    public double[] InputStreamScanner(int tail) {
        double[] read = new double[tail];
        for (int target = 0; target < tail; target++) {
            read[target] = nextDouble();
        }
        return read;
    }

    public String[] OutputWriter(int tail) {
        String[] read = new String[tail];
        for (int target = 0; target < tail; target++) {
            read[target] = nln();
        }
        return read;
    }

}

