import java.util.ArrayList;

public class Main {
	public static void main(String[] args) throws Exception {
		InputStreamReader is = new InputStreamReader(System.in);
		BufferedReader tokenizer = new BufferedReader(is);

		ArrayList<Integer> heart = new ArrayList<Integer>();

		while (true) {
			String number = tokenizer.readLine();
			if ("+".equals(init(number))) {
				heart.add(Integer.parseInt(selectionSort(number)) + Integer.parseInt(isPrime(number)));
			} else if ("-".equals(init(number))) {
				heart.add(Integer.parseInt(selectionSort(number)) - Integer.parseInt(isPrime(number)));
			} else if ("*".equals(init(number))) {
				heart.add(Integer.parseInt(selectionSort(number)) * Integer.parseInt(isPrime(number)));
			} else if ("/".equals(init(number))) {
				heart.add(Integer.parseInt(selectionSort(number)) / Integer.parseInt(isPrime(number)));
			} else if ("?".equals(init(number))) {
				for (int info = 0; info < heart.size(); info++) {
					System.out.println(heart.get(info));
				}
				break;
			}
		}
	}

	//?¬¬????????°???????????????????????????
	public static String selectionSort(String number) {
		int substringSecond = number.indexOf(" ");
		return (number.substring(0, substringSecond));
	}

	//	?¬¬????????°???????????????????????????
	public static String init(String number) {
		int index1 = number.indexOf(" ");
		int intL = number.lastIndexOf(" ");
		return (number.substring(index1 + 1, intL));
	}

	//	?¬¬????????°???????????????????????????
	public static String isPrime(String number) {
		int substringSecond = number.lastIndexOf(" ");
		return (number.substring(substringSecond + 1));
	}
}

