		//for(int i =1;i<m;i++){
		//C +=A*b}

		//n*mである行列Aの計算
		int[][] counts = new int[no][minNum];//Aの要素nとm
		String[] st = null; //実行データ用　文字列として使っているため0でなくnull
		for (int si = 0; si < no; si++) {//nのループ
