		try{
			BufferedReader tokenizer = new BufferedReader(new InputStreamReader(System.in));
			String[] stones = tokenizer.readLine().split(" ");
			int node = Integer.parseInt(stones[0]);
			int numberOfCoordinates = Integer.parseInt(stones[1]);
			int[][] table = new int[node][numberOfCoordinates];

			for (int dishes = 0; dishes < node; dishes++){
				String[] strLine = tokenizer.readLine().split(" ");
				for(int j = 0; j < numberOfCoordinates; j++){
					table[dishes][j] = Integer.parseInt(strLine[j]);
				}
			}

			int[][] numArrayInt = new int[node+1][numberOfCoordinates+1];
			int[] med = new int[numberOfCoordinates];
			int[] score = new int[node];
			int suit = 0;

			for (int tempC = 0; tempC < node+1; tempC++){
				if (tempC < node){
					for (int residence = 0; residence < numberOfCoordinates+1; residence++){
						if(residence < numberOfCoordinates){
							numArrayInt[tempC][residence] = table[tempC][residence];
							suit += numArrayInt[tempC][residence];
						}else{
							for (int a = 0; a < numberOfCoordinates; a++){
								score[tempC] += table[tempC][a];
								numArrayInt[tempC][residence] = score[tempC];
							}
						}
					}
				}else{
					for (int z = 0; z < numberOfCoordinates+1; z++){
						if (z < numberOfCoordinates){
							for (int values = 0; values < node; values++){
							med[z] += table[values][z];
							numArrayInt[tempC][z] = med[z];
							}
						}else{
							numArrayInt[tempC][z] = suit;
						}
					}
				}
			}

			for (int s = 0; s < node+1; s++){
				for (int st = 0; st < numberOfCoordinates+1; st++){
					if (st < numberOfCoordinates ){
						System.out.print(numArrayInt[s][st] + " ");
					}else{
						System.out.print(numArrayInt[s][st]);
					}
				}
				System.out.println();
			}
		}catch(IOException scanner){
		System.out.println(scanner);
		}
	}
}

