import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        FastReader maxn = new FastReader();
        String a = maxn.next();
        String d = maxn.next();
        if (a.length() <= d.length()) {
            System.out.println(get(a, d));
        } else {
            System.out.println(get(d, a));
        }
    }

    static int get(String list, String minIdx) {
        int line = list.length();
        int m = minIdx.length();

        int tail = Integer.MAX_VALUE;
        for (int result = 0; result < m - line + 1; result++) {
            int pattern = 0;
            for (int j = 0; j < line; j++) {
                if (list.charAt(j) != minIdx.charAt(result + j)) {
                    pattern++;
                }
            }

            tail = Math.min(pattern, tail);
        }

        return tail;
    }

    static class rec {
        BufferedReader cur;
        StringTokenizer rightMostGreatorIndex;

        public rec() {
            cur = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (rightMostGreatorIndex == null || !rightMostGreatorIndex.hasMoreElements()) {
                try {
                    rightMostGreatorIndex = new StringTokenizer(cur.readLine());
                } catch (IOException size) {
                    size.printStackTrace();
                }
            }
            return rightMostGreatorIndex.nextToken();
        }

        int readArray() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String ret = "";
            try {
                ret = cur.readLine();
            } catch (IOException size) {
                size.printStackTrace();
            }
            return ret;
        }
    }
}

