public class Main {
  public static void main(String[] args){
    Scanner scn = new Scanner(System.in);
    int maxium = scn.nextInt();
    int nl = scn.nextInt();
    int pro[] = new int[nl];
    int string[] = new int[nl];
    if(nl==0){
      System.out.println(maxium);
      return;
    }
    for(int sum_min = 0 ; sum_min < nl ; ++sum_min){
      pro[sum_min] = scn.nextInt();      
    }

    Arrays.sort(pro);

    int splits = 0;
    int st_s = 0;
    int ans = 0;
    int numberOfCoordinates = 0;


    //うえ
    for(int sum_min = maxium ; sum_min <= 101 ; ++sum_min){
      int counta=0;
      for(int med = 0 ; med < nl ; ++med){   
        if(pro[med] != sum_min){
          counta++; 
        }else if(pro[med] == sum_min){
          break;
        }
      }if(counta == pro.length){
        ans = sum_min;
        break;
      }
    }

    //した
    for(int sum_min = maxium ; sum_min >= 0 ; --sum_min){
      int counta=0;
      for(int med = 0 ; med < nl ; ++med){
        if(pro[med] != sum_min){
          counta++; 
        }else if(pro[med] == sum_min){
          break;
        }
      }if(counta == pro.length){
        numberOfCoordinates = sum_min;
        break;
      }
    }
    splits = Math.abs(maxium-ans);
    st_s = Math.abs(maxium-numberOfCoordinates);
