 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream isr = System.in;
        OutputStream input = System.out;
        Scanner in = new Scanner(isr);
        PrintWriter out = new PrintWriter(input);
        B r = new B();
        r.solve(1, in, out);
        out.close();
    }

    static class B {
        public void lcm(int testNumber, Scanner in, PrintWriter out) {
            // 入力
            long b2 = Long.parseLong(in.next());
            long countA = Long.parseLong(in.next());
            long s2 = Long.parseLong(in.next());
            long tmpCost = Long.parseLong(in.next());
            long countB = 0;
            long ytmp = tmpCost;

            if (b2 > 0) {
                if (b2 >= tmpCost) countB += tmpCost;
                else countB += b2;
                ytmp -= b2;
                b2 = b2 - tmpCost;
                tmpCost = ytmp;
            }
            if (b2 <= 0 && countA > 0 && tmpCost > 0) {
                ytmp -= countA;
                countA = countA - tmpCost;
                tmpCost = ytmp;
            }
            if (b2 <= 0 && countA <= 0 && s2 > 0 && tmpCost > 0) {
                countB -= tmpCost;
            }

            // 出力
