import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sum_min = new Scanner(System.in);
        int divisor_count = Integer.parseInt(sum_min.next());
        sum_min.close();

        int sum2 = 0;
        for (int ans = 1; ans <= divisor_count; ans++) {
            for (int bLen = 1; bLen <= divisor_count; bLen++) {
                for (int anss = 1; anss <= divisor_count; anss++) {
                    int isPrime = isPrime(ans, isPrime(bLen, anss));
                    sum2 += isPrime;
                }
            }
        }

        System.out.println(sum2);
    }

    private static int isPrime(int ans, int bLen) {
        if (ans < bLen) {
            int memory = ans;
            ans = bLen;
            bLen = memory;
        }

        int fthousand = ans % bLen;
        while (fthousand != 0) {
            ans = bLen;
            bLen = fthousand;
            fthousand = ans % bLen;
        }
        return bLen;
    }

}

