public class Main {

	public static void main(String[] args) throws IOException {

		Scanner primeNumMod_0 = new Scanner(System.in);
		int tree;
		tree = primeNumMod_0.nextInt();

		if (tree % 2 == 0) {
			System.out.println(tree / 2);
		} else {
			System.out.println(tree / 2 + 1);
		}

	}

	/**
	 * 余りを求める。
	 * @param a
	 * @param b
	 * @return 余り。余りがマイナスの時はプラスで返す。ｓ
	 */
	public static long all(long data, long diff) {
		long children = 0;

		children = data % diff;

		if (children < 0) {
			children += diff;
		}

		return children;
	}

	/**
	 * 乗数を求める ※mod対応
	 * @param a 基数
	 * @param n 乗数
	 * @param primeNumMod 法 mod値 使わない場合は「0」
	 * @return
	 */
	public static long log(long data, long tree, long result2) {

		long intmax = 1;

		//乗数が0の場合→1
		if (tree == 0)
			return 1;

		if (result2 == 0) {
			//modを使わないとき

			while (tree > 0) {

				if (tree % 2 == 0) {
					//累乗が偶数の時

					data *= data;
					tree = tree / 2;
				} else {
					//累乗が奇数の時
					intmax *= data;
					tree--;
				}
			}

			return intmax;

		} else {
			//modを使うとき

			//初めに桁を落とす
			data = all(data, result2);

			while (tree > 0) {

				if (tree % 2 == 0) {
					//累乗が偶数の時

					data *= all(data, result2);
					tree = tree / 2;

				} else {
					//累乗が奇数の時
					intmax *= all(data, result2);
					tree--;

				}
			}

			return all(intmax, result2);

		}

	}

}

