public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int r = scan.nextInt();

        int[] difference = new int[r];

        int dist = 100;
        int maxPosition = 1;
        for (int list2 = 0; list2 < r; list2++) {
            int minval = scan.nextInt();
            dist = Math.min(dist, minval);
            maxPosition = Math.max(maxPosition, minval);
            difference[list2] = minval;
        }

        int minValue = Integer.MAX_VALUE;
        for (int prime = dist; prime <= maxPosition; prime++) {
            int minval = 0;
            for (int list2 = 0; list2 < r; list2++) {
                minval += primeList(difference[list2], prime);
            }
            minValue = Math.min(minValue, minval);
        }
        System.out.println(minValue);
    }

    private static int primeList(int personStamina, int maxAIndex) {
        return (int) Math.pow(personStamina - maxAIndex, 2);
    }
}

