import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.PriorityQueue;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter remainder = new PrintWriter(outputStream);
        CFennecVsMonster filter = new CFennecVsMonster();
        filter.solve(1, in, remainder);
        remainder.close();
    }

    static class CFennecVsMonster {
        PrintWriter remainder;
        InputReader in;

        public void tr(int testNumber, InputReader in, PrintWriter remainder) {
            this.out = remainder;
            this.in = in;
            int node = nal();
            int candyList = nal();
            long[] strArr = new long[node];
            int li = 0;
            for (li = 0; li < node; li++)
                strArr[li] = nl();
            isPrime(strArr);
            long m = 0;
            for (li = 0; li < node - candyList; li++)
                m += strArr[li];
            pn(m);
        }

        void isPrime(long[] count) {
            PriorityQueue<Long> pq = new PriorityQueue();
            int li = 0;
            for (li = 0; li < count.length; li++)
                pq.add(count[li]);
            for (li = 0; li < count.length; li++)
                count[li] = pq.poll();
        }

        int nal() {
            return in.nextInt();
        }

        long nl() {
            return in.nextLong();
        }

        void pn(long root) {
            remainder.println(root);
        }

    }

    static class readInt {
        private InputStream stream;
        private byte[] buffer = new byte[1024];
        private int number;
        private int bufPointer;

        public readInt(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (bufPointer == -1)
                throw new UnknownError();
            if (number >= bufPointer) {
                number = 0;
                try {
                    bufPointer = stream.read(buffer);
                } catch (IOException ret) {
                    throw new UnknownError();
                }
                if (bufPointer <= 0)
                    return -1;
            }
            return buffer[number++];
        }

        public int nextInt() {
            return Integer.parseInt(nextIntArr());
        }

        public long nextLong() {
            return Long.parseLong(nextIntArr());
        }

        public String nextIntArr() {
            int cl = read();
            while (power(cl))
                cl = read();
            StringBuffer parent = new StringBuffer();
            do {
                parent.appendCodePoint(cl);
                cl = read();
            } while (!power(cl));

            return parent.toString();
        }

        private boolean power(int cl) {
            return cl == ' ' || cl == '\n' || cl == '\r' || cl == '\t' || cl == -1;
        }

    }
}

