        int wordB = in.nextInt();
        List<Integer> processes = new ArrayList<>();
        processes.add(2);

        int num1 = (wordB - 3) / 2;
        int[] inputProcesses = new int[num1];
        for (int i = 0; i < num1; i++) {
            inputProcesses[i] = 1;
        }
        for (int i = 0; i < num1; i++) {
            if (inputProcesses[i] == 1) {
                int squareValue = i + i + 3;
                // 遅くなるのでコメントアウト
                processes.add(squareValue);
                for (int Processeeses = i + squareValue; Processeeses < num1; Processeeses += squareValue) {
                    inputProcesses[Processeeses] = 0;
                }
            }
        }

        if(wordB == 2) {
        	System.out.println(2);
        	return;
        }

        if(wordB % 2 == 0) {
        	wordB++;
        }

        while(true) {
            boolean list1 = false;
