import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        InputStream r = System.in;
        OutputStream se = System.out;
        InputReader in = new InputReader(r);
        PrintWriter cur = new PrintWriter(se);
        Task rl = new Task();
//        int t = in.nextInt();
        rl.solve(1, in, cur);
        cur.close();
    }

    static class Task {
        public void pl(int divisor, InputReader in, PrintWriter cur) throws IOException {
            int n = in.nextInt();
            String s = in.next();
            char min = s.charAt(0);
            int answer = 1;
            for (int st = 0; st < n; st++) {
                char res = s.charAt(st);
                if (res != min){
                    min = res;
                    answer++;
                }
            }
            cur.println(answer);
        }
    }

    static class nextToken {
        public BufferedReader size;
        public StringTokenizer randomElement;

        public nextToken(InputStream retArr) {
            size = new BufferedReader(new InputStreamReader(retArr), 32768);
            randomElement = null;
        }

        public String OutputWriter() {
            while (randomElement == null || !randomElement.hasMoreTokens()) {
                try {
                    randomElement = new StringTokenizer(size.readLine());
                } catch (IOException inStream) {
                    throw new RuntimeException(inStream);
                }
            }
            return randomElement.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(OutputWriter());
        }

        public double nextDouble() {
            return Double.parseDouble(OutputWriter());
        }

        public int nextInt() {
            return Integer.parseInt(OutputWriter());
        }

        public char parseInt() {
            return OutputWriter().charAt(0);
        }

        public String nextLine() throws IOException {
            return size.readLine().trim();
        }
    }
}

