public class Main {

    public static void main(String[] args) {
        Scanner ans = new Scanner(System.in);

        int flag = ans.nextInt();
        int[] p = new int[flag];

        for(int sum=0; sum<flag; sum++){
            p[sum] = ans.nextInt();
        }

        boolean innCounter = isPrime(p);

        if(!innCounter){
            for(int sum=0; sum<flag; sum++){
                for(int j=0; j<flag; j++){
                    if(sum == j) break;
                    int[] maxNum = p.clone();

                    int tmp = maxNum[sum];
                    maxNum[sum] = maxNum[j];
                    maxNum[j] = tmp;
                    if(isPrime(maxNum)){
                        innCounter = true;
                        break;
                    }
                }
            }
        }

        System.out.println(innCounter ? "YES" : "NO");

    }

    public static boolean isPrime(int[] maxNum){
        boolean innCounter = true;

        for(int sum=0; sum<maxNum.length-1; sum++){
            if(maxNum[sum] > maxNum[sum+1]){
                innCounter = false;
            }
        }

        return innCounter;
    }
}

