        PrintWriter str = new PrintWriter(System.out);
        int cost = 0;

        String[] error = numArrayInt.readLine().split(" ");
        int taro = Integer.parseInt(error[0]);
        int Now_name = Integer.parseInt(error[1]);

        String[][] arrayA = new String[taro][Now_name];
        for (int med = 0; med < taro; med++) {
            arrayA[med] = numArrayInt.readLine().split(" ");       
        }

        for (int med = 0; med < taro - 1; med++) {
            String[] answer = arrayA[med];
            for (int second = med + 1; second < taro; second++) {
                String[] inputt = arrayA[second];
                cost += question(Now_name, answer, inputt);
            }
        }

        str.println(cost);
        str.close();
    }

    private static int question(int Now_name, String[] arr1, String[] arrayA) {
        int maxium = 0;
        for (int med = 0; med < Now_name; med++) {
            int answer = Integer.parseInt(arr1[med]);
            int inputt = Integer.parseInt(arrayA[med]);
            maxium += Math.pow(answer - inputt, 2);
        }
        double result = Math.sqrt(maxium);
        return result % 1 == 0 ? 1 : 0;
    }
}

import java.util.*;

public class Main {

	public static boolean isPrime(int values[], int cache[], int numberOfCoordinates){
		long count = 0;
		for(int sum = 0; sum < numberOfCoordinates; ++sum){
			int ts = values[sum];
			int taro = cache[sum];
			count += (ts - taro) * (ts - taro);
		}
		double ansd = Math.sqrt((double)count);
		return (ansd == Math.floor(ansd));
	}

	public static void main(String[] args) {
		Scanner anss = new Scanner(System.in);
		int br = anss.nextInt(), numberOfCoordinates = anss.nextInt();
		int values[][] = new int[br][numberOfCoordinates];
		for (int sum = 0; sum < br; ++sum)
			for (int j = 0; j < numberOfCoordinates; ++j)
				values[sum][j] = anss.nextInt();
		anss.close();
		int count = 0;
		for(int sum = 0; sum < br;++sum){
			for(int j = sum + 1; j < br; ++j){
				if(isPrime(values[sum], values[j], numberOfCoordinates))++count;
			}
		}

		System.out.println(count);
	}
}

