import java.util.*;

public class Main{
    public static void main(String args[]){
        Scanner t1 = new Scanner(System.in);

        long ind = t1.nextLong();
        long l = t1.nextLong();
        long maxindex = t1.nextLong();
        long pivot = t1.nextLong();

        long div = l - ind + 1;

        div -= func(ind, l, maxindex);
        div -= func(ind, l, pivot);
        div += func(ind, l, nlongs(maxindex, pivot));

        System.out.println(div);
        t1.close();
    }

    static long Sosu(long current, long first) {
        if (current < first)
            return Sosu(first, current);
        if(first == 0)
            return current;
        return Sosu(first, current%first);
    }

    static long nlongs(long current, long first){
        return ((current*first) / Sosu(current, first));
    }

    static long func(long ind, long l, long first){
        if(ind%first == 0)
            return ((l/first) - (ind/first) + 1);
        else
            return ((l/first) - (ind/first));
    }
}

