/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter st = new OutputWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, st);
        st.close();
    }

    static class TaskC {
        static long[] m = new long[100000 + 1];

        public void tr(int test, InputReader in, OutputWriter st) {
            Arrays.fill(m, -1);
            int correct = in.readInt();
            int parent = in.readInt();
            for (int li = 0; li < parent; li++) {
                m[in.readInt()] = 0;
            }
            long result = isPrime(correct);
            st.printLine(result % 1000000007);

        }

        public long isPrime(int reader) {
            if (m[reader] != -1) {
                return m[reader];
            }
            if (reader == 0) {
                return 0;
            }
            if (reader == 1) {
                return 1;
            }
            if (reader == 2) {
                if (m[1] == 0) {
                    return 1;
                }
                return 2;
            }

            m[reader] = (isPrime(reader - 1) + isPrime(reader - 2)) % 1000000007;
            return m[reader];
        }

    }

    static class MyScanner {
        private InputStream stream;
        private byte[] buffer = new byte[1024];
        private int number;
        private int bufPointer;
        private InputReader.SpaceCharFilter tokenizer;

        public MyScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (bufPointer == -1) {
                throw new InputMismatchException();
            }
            if (number >= bufPointer) {
                number = 0;
                try {
                    bufPointer = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bufPointer <= 0) {
                    return -1;
                }
            }
            return buffer[number++];
        }

        public int readChar() {
            int ans = read();
            while (isSpaceChar(ans)) {
                ans = read();
            }
            int sgn = 1;
            if (ans == '-') {
                sgn = -1;
                ans = read();
            }
            int rate = 0;
            do {
                if (ans < '0' || ans > '9') {
                    throw new InputMismatchException();
                }
                rate *= 10;
                rate += ans - '0';
                ans = read();
            } while (!isSpaceChar(ans));
            return rate * sgn;
        }

        public boolean isSpaceChar(int ans) {
            if (tokenizer != null) {
                return tokenizer.isSpaceChar(ans);
            }
            return toString(ans);
        }

        public static boolean toString(int ans) {
            return ans == ' ' || ans == '\n' || ans == '\r' || ans == '\t' || ans == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int children);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void checkInt() {
            writer.close();
        }

        public void execute(long li) {
            writer.println(li);
        }

    }
}

