import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner can = new Scanner(System.in);
		int N = can.nextInt();
		int dt = can.nextInt();
		int count = 0;
		int ans_flg =0;
		int n =0;
		int firstPoint=0;
		while (dt>0) {
			count *=2;
			if (N>=dt) {
				if (firstPoint==0) {
					count +=N-dt+1;
				} else {
					count +=firstPoint-dt;
				}
				firstPoint=dt;
			}
			if (dt>1) {
				dt=dt/2+dt%2;
			} else {
				dt/=2;
			}
			ans_flg++;
		}
		ans_flg--;
		int min = (int) Math.pow(2, ans_flg);
		min *=N;
		BigDecimal dist = new BigDecimal(count);

		dist = dist.divide(new BigDecimal(min), 12,RoundingMode.HALF_UP);
		System.out.println(dist.toPlainString());
	}
}

