public class Main {
	Scanner sum = new Scanner(System.in);

	static int cost;
	void printPossibleBlack() {
		int n = sum.nextInt();
		int[] temperature = new int[n];
		int maxCount = 101;
		cost = 0;
		for(int i = 0; i < n; i++) {
			temperature[i] = sum.nextInt();
			if(temperature[i] < maxCount)maxCount = temperature[i];
		}
		getTime(temperature, 0, n - 1, 0);
		System.out.println(cost);
	}

	void getTime(int[] temperature, int ans, int streakAry, int isNotPrime) {
		if(ans > streakAry)return;
		int maxCount = 101, med = -1;
		for(int i = ans; i <= streakAry; i++) {
			if(maxCount > temperature[i]) {
				maxCount = temperature[i];
				med = i;
			}
		}
		cost += maxCount - isNotPrime;
		if(maxCount <= isNotPrime)maxCount = isNotPrime;
		if(maxCount - isNotPrime == 0) isNotPrime = 0;
		getTime(temperature, ans, med - 1, maxCount);
		getTime(temperature, med + 1, streakAry, maxCount);
	}
	public static void main(String[] args) {
		new Main().doIt();
	}
}

