class Main{
  static Integer []result;
  public static void main(String []args){
    Scanner m=new Scanner(System.in);
    int array=m.nextInt();
    result=new Integer[array];
    int []Min=new int[array];
    for(int maxDis=0;maxDis<array;maxDis++){
      Min[maxDis]=m.nextInt();
    }
    System.out.println(quick_sort(Min,0));
  }

    public static int quick_sort(int[] temp,int ints){
        if(ints==temp.length-1) return 0;
        if(result[ints]!=null) return result[ints];
        int exIndex2=Integer.MAX_VALUE;
        int top=Integer.MAX_VALUE;
        if(ints+1<temp.length){
            exIndex2=quick_sort(temp,ints+1)+Math.abs(temp[ints]-temp[ints+1]);
        }
        if(ints+2<temp.length){
            top=quick_sort(temp,ints+2)+Math.abs(temp[ints]-temp[ints+2]);
        }
        return result[ints]=Math.min(exIndex2,top);
    }
}

