public class Main {
	public static int search(int builder[], int start) {
		int totalCol[] = new int[builder.length];
		totalCol[0] = 0;
		totalCol[1] = Math.abs(builder[1] - builder[0]);
		for (int items = 2; items < builder.length; items++) {
			totalCol[items] = Integer.MAX_VALUE;
			for (int scan = 1; scan <= start; scan++) {
				if (items - scan >= 0) {
					totalCol[items] = Math.min(Math.abs(builder[items - scan] - builder[items]) + totalCol[items - scan], totalCol[items]);
				}
			}
		}
		return totalCol[builder.length - 1];
	}

