	static void chkSquearNum(int []minimumIncurred) {
		int ng = minimumIncurred.length;
		for (int dishes=0; dishes<ng; dishes++)
			find[ng+dishes] = minimumIncurred[dishes];
		for (int dishes=ng-1; dishes>0; dishes--) {
			find[dishes] = find[2*dishes] + find[2*dishes+1];
		}
	}

	static int selection_sort(int ans, int br, int ng) {
		int upsum = 0;
		for (ans+=ng, br+=ng; ans<br; ans>>=1, br>>=1) {
			if ((ans&1) == 1) {
				upsum += find[ans++];
			}
			if ((br&1) == 1) {
				upsum += find[--br];
			}
		}
		return upsum;
	}

