    }
    public static int minCostRecursive(int arr,int m,int[] total) {
        int points[]=new int[arr];
        points[1]=Math.abs(total[0]-total[1]);
        for(int ts=2;ts<arr;ts++) {
            points[ts]=Integer.MAX_VALUE;
            for(int ienozahyo=1;ienozahyo<=Math.min(ts,m);ienozahyo++) {
