public class Main {
  public static void main(String[] args) {
    Scanner ret = new Scanner(System.in);
    try {
      int ad = ret.nextInt();
      int r = ret.nextInt();
      int answerR = isPrime(ad, r);
      System.out.println(answerR);
    } finally {
      ret.close();
    }
  }

  private static int isPrime(int ad, int r) {
    // n = 100がコーナーケース（罠）
    // d = 0の時を考える。ちょうど0回割り切れる＝割り切れないだが、
    // 100で割り切れない100番目に小さい数は101
    if (r == 100) r++;
    for (int idx = 0; idx < ad; idx++) r *= 100;
    return r;
  }
}

