		boolean x = false;
		int list = ans.length - 1;
		int change_cnt = 0;
		for (int minCost = 0; minCost < ans.length / 2; minCost++) {
			if (ans[minCost] == ans[list - minCost])
				change_cnt++;
		}
		if (change_cnt == ans.length / 2)
			x = true;
		return x;
	}

}

