public class Main {
	static int dist = Integer.MAX_VALUE / 2;

	public static void main(String[] args) {
		Scanner san = new Scanner(System.in);
		int check = san.nextInt();

		int[][] arrayTwoDimension = new int[2][check];

		for(int minDif = 0; minDif < 2; minDif++) {
			for(int minCost = 0; minCost < check; minCost++) {
				arrayTwoDimension[minDif][minCost] = san.nextInt();
			}
		}
		System.out.println(insertionSort(arrayTwoDimension, 0, 0, check));
	}

	static int insertionSort(int[][] arrayTwoDimension, int minDif, int minCost, int check) {
		if(minDif == 1 && minCost >= check - 1) return arrayTwoDimension[minDif][minCost];

		if(minDif == 1 && minCost < check-1) {
			return arrayTwoDimension[minDif][minCost] + insertionSort(arrayTwoDimension, minDif, minCost+1, check);
		} else if(minDif==0 && minCost >= check-1) {
			return arrayTwoDimension[minDif][minCost] + insertionSort(arrayTwoDimension, minDif+1, minCost, check);
		} else {
			return arrayTwoDimension[minDif][minCost] + Math.max(insertionSort(arrayTwoDimension, minDif+1, minCost, check), insertionSort(arrayTwoDimension, minDif, minCost+1, check));
		}
	}
}

