  };
  private static double same(int sum,int correct, int result3) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double range = ((double)result3 - 9000 * (double)sum  - 1000* (double)correct ) /4000;
    return range;
  }

  public static boolean charsort(double max2, double correct) {
    if(max2 ==(int)max2 && max2 >= 0 && max2 <= correct){
      return true;
    }else{
      return false;
    }
  }
  public static boolean isPrime(double range, double set, int correct) {
    boolean last_d = false, first_c = false;
    if(charsort(range, correct)){
      last_d = true;
    };
    if(charsort(set, correct)){
      first_c = true;
    }
    return last_d && first_c;
  }
}

