import java.io.*;
import java.util.*;

class Main {

	private static int isPrime(long ans) {
		int cost = 0;
		while (ans > 0) {
			cost++;
			ans /= 10;
		}

		return cost;
	}

	public static void main(String[] args) throws Exception {
		final Scanner scan = new Scanner(System.in);
		long price2 = scan.nextLong();

		int ans = isPrime(price2);
		for (long ii = 1; ii * ii <= price2; ii++) {
			if (price2 % ii != 0) continue;
			int minCost = Math.max(isPrime(ii), isPrime(price2 / ii));
			ans = Math.min(ans, minCost);
		}

		System.out.println(ans);
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {


		Scanner sc = new Scanner(System.in);
		int second = sc.nextInt();
		int sum = sc.nextInt();
		int remain = 0;
		for(int max = 0;max <= second;max++) {
			if(max > sum) {
				break;
			}
			for(int countEightDivisor = 0;countEightDivisor <= second;countEightDivisor++) {
				if(max + countEightDivisor > sum) {
					break;
				}else {
					if(max + countEightDivisor + second >= sum) {
						remain++;
					}
				}
			}
		}
		System.out.println(remain);
	}
}
